package pl.zagranietyper.service;import org.junit.jupiter.api.Test;import pl.zagranietyper.model.*;import pl.zagranietyper.parser.FootballEventPlayerPositiveSyntaxAdapter.Family;import pl.zagranietyper.repository.FootballFixtureEventsRepository;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FootballEventPlayerPositiveSettlementEngineTest {private final FootballEventPlayerPositiveSettlementEngine e=new FootballEventPlayerPositiveSettlementEngine();private static FootballFixtureEventsSnapshot.Event event(int i,String type,String detail,Long player,Long assist){return new FootballFixtureEventsSnapshot.Event(i,1L,"T",player,player==null?null:"P. One",assist,assist==null?null:"A. Two",type,detail,10,null,null);}private static FootballFixtureEventsRepository.FixtureTimeline tl(FootballFixtureEventsSnapshot.Event...x){return new FootballFixtureEventsRepository.FixtureTimeline(1,FootballFixtureEventsSnapshot.FetchStatus.COMPLETE,1L,2L,List.of(x));}@Test void scorerNormalAndPenaltyWin(){assertEquals(SettlementDecision.W,e.settle(Family.ANYTIME_SCORER,"P One",tl(event(0,"Goal","Normal Goal",7L,null))).decision());assertEquals(SettlementDecision.W,e.settle(Family.ANYTIME_SCORER,"P One",tl(event(0,"Goal","Penalty",7L,null))).decision());}@Test void absenceCancelledAndOwnGoalNeverLoseOrWin(){assertEquals(SettlementDecision.UNSUPPORTED,e.settle(Family.ANYTIME_SCORER,"P One",tl(event(0,"Card","Yellow Card",7L,null))).decision());assertEquals(SettlementDecision.UNSUPPORTED,e.settle(Family.ANYTIME_SCORER,"P One",tl(event(0,"Var","Goal cancelled",7L,null))).decision());assertEquals(SettlementDecision.UNSUPPORTED,e.settle(Family.ANYTIME_SCORER,"P One",tl(event(0,"Goal","Own Goal",7L,null))).decision());}@Test void assistNeedsPositiveNonNullMatch(){assertEquals(SettlementDecision.W,e.settle(Family.PLAYER_ASSIST,"A Two",tl(event(0,"Goal","Normal Goal",7L,8L))).decision());assertEquals(SettlementDecision.UNSUPPORTED,e.settle(Family.PLAYER_ASSIST,"A Two",tl(event(0,"Goal","Normal Goal",7L,null))).decision());}}
